const n=[{name:"Cloudflare",hooks:["dns_cf"],ns:/(^|\.)ns\.cloudflare\.com$/},{name:"GoDaddy",hooks:["dns_gd"],ns:/(^|\.)domaincontrol\.com$/},{name:"Route 53",hooks:["dns_aws"],ns:/(^|\.)awsdns-\d+\.(com|net|org|co\.uk)$/},{name:"DigitalOcean",hooks:["dns_dgon"],ns:/(^|\.)digitalocean\.com$/}];export function hookProvider(e){if(!e)return null;const o=n.find(n=>n.hooks.includes(e));return o?o.name:null}export function nsProvider(e){if(!e||!e.length)return null;for(const o of n)if(e.some(n=>o.ns.test(String(n).replace(/\.$/,"").toLowerCase())))return o.name;return null}export async function zoneNs(n,e){let o=String(n).replace(/\.$/,"").split(".");for(;o.length>=2;){const n=o.join(".");try{const o=await e(n);if(o&&o.length)return{zone:n,ns:o}}catch{}o=o.slice(1)}return null}export function explain(n,e,o){const t=hookProvider(n);if(!t)return null;if(!e||!e.length)return null;const r=o||"the zone",s=nsProvider(e);return s===t?null:s?`acme.sh validates through ${t}, but ${s} holds ${r} — the challenge is being written where nothing reads it`:`acme.sh validates through ${t}; the nameservers for ${r} are ${e.join(", ")}`}